import{_ as i,l as n,o as e,c as o,v as r,p,x as t,d as s,i as d,S as P}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"滑点归因","description":"","frontmatter":{"title":"滑点归因","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/slippage-attribution.md","filePath":"quant/slippage-attribution.md","lastUpdated":1789023840000}'),h={name:"quant/slippage-attribution.md"};function m(_,a,E,A,u,B){const l=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="滑点归因" tabindex="-1">滑点归因 <a class="header-anchor" href="#滑点归因" aria-label="Permalink to &quot;滑点归因&quot;">​</a></h1><div class="epigraph"><p>纸面与成交之间的差可以拆成延误、价差、冲击、时机与未完成；不拆开，交易台就无法知道该修时钟、改切片，还是该承认信号已经走掉。</p><footer>—— 据 Perold 实施缺口与 Kissell 扩展分解整理</footer></div><p><a href="/quant/implementation-shortfall">实施缺口</a> 给出一个总额：决策价到真实组合的价值差。滑点归因要把总额拆成可行动的几项。总额低并不能说明算法好——可能只是信号没有动；总额高也不能说明算法差——可能是内部延误把到达价已经做坏。Kissell 等人把扩展实施缺口写成决策到下单、下单到首次成交、过程中的市场运动、即时成本与机会成本。交易台需要的是同一套会计在母单、算法、标的、场所上都能加总。本篇写拆项定义、反事实假设与常见串项，滑点在这里是执行质量的度量，不是「再找一个更激进的路由就一定能省下来」的承诺。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>买入母单目标 \\(Q\\)、决策价 \\(P_d\\)、到达交易所时的中间价 \\(P_a\\)、成交量 \\(q\\)、成交均价 \\(\\bar P\\)、窗口结束价 \\(P_e\\)、显式费用 \\(F\\)。总额</p> \\[\\mathrm{IS}= q(\\bar P-P_d)+(Q-q)(P_e-P_d)+F \\]<p>混了至少五类经济对象。内部延误 \\(P_a-P_d\\) 是投资经理到执行台的时钟；即时成本是相对当时报价的半价差与走档；冲击是自身流量对中点的写入，含瞬时与永久；时机是执行窗口内与自身无关的价格运动；机会成本是未完成。问题是给出一套加总为 IS 的拆项，使每一项对应一个负责人或一条规则，并且在部分成交、多日、公司行动下仍可算。</p><p>若不拆，激励会扭曲。只看 \\(\\bar P\\) 相对 VWAP，延误与未完成消失。只看 \\(\\bar P-P_a\\)，内部延误被藏在投资经理账上。只看完成率，交易台会用市价清扫换完成，把冲击做大。归因的第一句话是：每一项必须能被某项操作独立地移动，否则那一项只是残差的别名。</p><h3 id="到达价不是决策价" tabindex="-1">到达价不是决策价 <a class="header-anchor" href="#到达价不是决策价" aria-label="Permalink to &quot;到达价不是决策价&quot;">​</a></h3><p>\\(P_d\\) 是信号触发或组合优化器给出目标的时刻；\\(P_a\\) 是母单被交易所（或算法引擎）接受、可用于对照公开中点的时刻。两者之差包含人工确认、风控审批、系统排队与时钟不同步。把它并进「市场冲击」，算法永远无法解释开盘后三分钟才开始的母单为什么短fall 大。操作化上，交易台 KPI 用到达价；公司层面 IS 用决策价；中间的延误单独一张表。三套数字必须能对上，不能各说各的「滑点」。</p><p><span class="marginnote">结束价 \\(P_e\\) 只在「结束时仍想要未完成量」时适合标记机会成本。信号已撤、目标已改，应在撤销时刻关闭第二项，否则事后 alpha 会混进执行质量。Kissell 分解对这一点敏感，规则要事先写进母单状态机。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一个可加总的到达价分解（买入、价格越高质量越差）：</p> \\[\\begin{aligned} q(\\bar P-P_d) &amp;= q(P_a-P_d) + q(\\bar P-M_{\\mathrm{during}}-s_{\\mathrm{eff}}) + q(s_{\\mathrm{eff}}) + q(M_{\\mathrm{during}}-P_a). \\end{aligned} \\]<p>第一项延误；第三项即时成本，用成交时有效价差或报价半价差代理，见 <a href="/quant/spread-cost">价差成本</a>；第四项是窗口内中点运动，含自身冲击与外生时机，需要再拆；第二项是残差（费用已另计则此处可去掉 \\(F\\)）。外生时机用对照：同期指数、行业、或不交易的相似股票。自身冲击 \\(\\approx\\) 总中点运动减对照。对照不是真的反事实——没有完全相似的未交易股票——但比把全部中点运动叫做冲击要诚实。</p><p>未完成项 \\((Q-q)(P_e-P_d)\\) 再拆：因涨跌停 / 无对手而不成，与因限价过被动而不成。前者是市场约束，后者是切片与定价规则。场所归因把 \\(q(\\bar P-P_a)\\) 按成交场所分摊，但分摊前必须把路由选择本身当成决策：去薄的场所可能即时成本低、冲击高。</p><h3 id="子单层与母单层不要用同一套科目" tabindex="-1">子单层与母单层不要用同一套科目 <a class="header-anchor" href="#子单层与母单层不要用同一套科目" aria-label="Permalink to &quot;子单层与母单层不要用同一套科目&quot;">​</a></h3><p>母单层回答「这笔决策亏在哪一类摩擦」。子单层回答「哪一类指令、哪个桶」。把每一笔子单相对当时中点的短fall 加总，不等于母单相对 \\(P_a\\) 的短fall：子单中点已经含前面子单的冲击，加总会重复计算永久项。正确的做法是：母单用到达价一次；子单只用过程内指标（相对当时报价的即时成本、排队等待、撤单率），用于改 <a href="/quant/child-order-slicing">子单切片</a>，不用于向投资委员会汇报 IS。混用会把算法显得很差或很好，取决于你是否把已移动的中点当新的零点。</p><p>多日母单要把隔夜跳空单独列为一项，不要并进冲击：你隔夜并未交易。开盘拍卖成交相对前收的跳开，是拍卖发现，不是连续冲击，见 <a href="/quant/close-auction-imbalance">收盘竞价不平衡</a> 的对称开盘情形。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>归因能改变行为，是因为它把一张账单拆成不同的生产函数。延误由工作流与系统；即时成本由订单类型与价差体制；冲击由参与率、切片与核；时机由 \\(T\\) 与是否选择交易；机会成本由完成约束与限价激进程度。Perold 的贡献是坚持决策时刻的纸面；Kissell 的贡献是坚持拆到可操作。机制上的风险是<strong>串项</strong>：把冲击叫做时机（对照没做好），交易台会去「择时」而不是降参与；把延误叫做冲击，工程团队不会去修时钟。</p><p>永久冲击特别容易串。自身交易写入中点后，对照若也含同类拥挤流，冲击被低估、时机被高估；对照若完全不含，拥挤被算成你的冲击。事先约定对照集合，比事后挑一只「看起来合理」的指数更重要。Huberman–Stanzl 的线性永久项在归因里应表现为与总量成比例、与路径关系弱的一块；若「冲击」随切片方式剧烈变化，你测到的多半仍是瞬时，窗口不够长。</p><p><span class="marginnote">负的即时滑点很常见：限价成交、价格改善。不要用它证明交易台在「卖流动性赚钱」。逆向选择会在更长窗口出现在中点运动或后续损益里。归因窗口与投资地平不一致时，符号会对不上。</span></p><h3 id="基准选择如何改写每一项的大小" tabindex="-1">基准选择如何改写每一项的大小 <a class="header-anchor" href="#基准选择如何改写每一项的大小" aria-label="Permalink to &quot;基准选择如何改写每一项的大小&quot;">​</a></h3><p>到达价归因与 VWAP 归因不是同一张表的单位换算。相对 VWAP 的「赢」可以全部来自 \\(P_{\\mathrm{VWAP}}-P_a\\) 这一段市场运动，你只是没有比市场成交更差。把 VWAP 赢拆进冲击项，会在单边市里奖励慢执行。正确映射是：VWAP 偏离 \\(\\approx\\) 即时成本 + 自身冲击 − 你与市场成交量曲线的错位；它几乎不含延误（若 \\(P_d\\) 不用）且不含未完成。治理上应禁止用 VWAP 项去解释 IS 总额的下降。收盘价基准会激励把冲击堆到尾盘，收盘拍卖不平衡被当成「免费流动性」——流动性有价格，见竞价篇。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>反事实永远有设定误差。暗池成交没有同时刻公开中点，即时成本偏。外汇与期货的点差、展期、资金费应有单独科目，不要塞进股票式「价差」。加密永续的资金费是持仓的期间成本，不是开仓滑点，见 <a href="/quant/crypto-perp-funding">永续合约资金费率</a>。公司行动日要用调整后价格对齐纸面与真实，否则归因会出现一次性跳点。</p><p>统计上单笔噪声极大，比较算法必须在大量母单上、按紧急程度与波动分层。不要在样本内挑选「归因后冲击最低」的参数组合再报告：那是对拆项规则与对照的过拟合。参数应预先锁定，归因表用于监控漂移（延误突然变长、尾盘清扫占比上升），而不是用于证明某一季度执行 alpha 为负。</p><p>不要把滑点归因当成交易信号。观测到「时机项为负」（窗口内价格对你有利）不等于应该永远等：那是样本路径。把归因残差拿去训练下一次的自适应 \\(\\rho\\)，很容易把噪声写成规则。若要闭环，应用样本外母单、预先登记的规则变更，而不是每日重估科目权重。</p><p><span class="marginnote">显式费用 \\(F\\) 看起来最干净，仍有口径：是否含过户、印花、交易所返佣、暗池费用。返佣若记成负费用，会把路由推向返佣高的场所，冲击项恶化。费用科目应与路由激励分开审计。</span></p>',30)),(e(),p(P,null,{default:t(()=>[d(l,{id:"mermaid-84",class:"mermaid",graph:"flowchart%20TD%0A%20%20Pd%5B%22%E5%86%B3%E7%AD%96%E4%BB%B7%20Pd%22%5D%20--%3E%20Del%5B%22%E5%BB%B6%E8%AF%AF%3A%20Pa-Pd%22%5D%0A%20%20Pa%5B%22%E5%88%B0%E8%BE%BE%E4%BB%B7%20Pa%22%5D%20--%3E%20Spr%5B%22%E5%8D%B3%E6%97%B6%3A%20%E6%9C%89%E6%95%88%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20Pa%20--%3E%20Imp%5B%22%E8%87%AA%E8%BA%AB%E5%86%B2%E5%87%BB%22%5D%0A%20%20Pa%20--%3E%20Tim%5B%22%E5%A4%96%E7%94%9F%E6%97%B6%E6%9C%BA%22%5D%0A%20%20Spr%20--%3E%20Avg%5B%22%E6%88%90%E4%BA%A4%E5%9D%87%E4%BB%B7%22%5D%0A%20%20Imp%20--%3E%20Avg%0A%20%20Tim%20--%3E%20Avg%0A%20%20Avg%20--%3E%20IS%5B%22%E5%AE%9E%E6%96%BD%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20Unf%5B%22%E6%9C%AA%E5%AE%8C%E6%88%90%20%C3%97%20(Pe-Pd)%22%5D%20--%3E%20IS%0A%20%20F%5B%22%E6%98%BE%E5%BC%8F%E8%B4%B9%E7%94%A8%22%5D%20--%3E%20IS%0A%20%20Del%20--%3E%20IS%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>滑点归因把实施缺口拆成延误、即时成本、自身冲击、外生时机、未完成与费用，使每一项对应可改的规则。</li><li>决策价与到达价必须分开；交易台 KPI 用到达价，公司 IS 用决策价，延误单独披露。</li><li>自身冲击依赖对照，对照集合要事先约定；窗口过短会把瞬时当作永久。</li><li>子单短fall 加总会重复计算已移动的中点，不能代替母单到达价会计。</li><li>VWAP 赢亏不能用来解释 IS；收盘基准会把冲击推向拍卖。</li><li>负即时滑点不等于执行创造了 alpha；逆向选择在更长窗口。</li><li>出处：Perold, <em>The Implementation Shortfall</em>, Journal of Portfolio Management, 1988；Kissell 等对扩展实施缺口的分解；Almgren and Chriss, <em>Journal of Risk</em>, 2000/2001；价差口径见 Hasbrouck, <em>Journal of Finance</em>, 2009。</li></ul>',2))])}const q=i(h,[["render",m]]);export{f as __pageData,q as default};
